 void toggle(MainActivity a){if(busy){status="Please wait for the current VPN operation";notifyChanged();return;}if(active){context.startService(new Intent(context,BladesVpnService.class).setAction("disconnect"));return;}if(!configured()){openSettings(a);return;}if(anotherVpn()){status="Another VPN is active. Disconnect it before using PIA here.";notifyChanged();return;}Intent consent=VpnService.prepare(a);if(consent!=null){status="Waiting for Android VPN permission";a.startActivityForResult(consent,CONSENT);notifyChanged();}else begin();}
